# Proper 4-way mirror - check bounds

height = 13
width = 11

test_input = [
    [2, 2, 2, 6, 2, 2, 2, 6, 2, 2, 2],
    [2, 2, 2, 6, 2, 2, 2, 6, 2, 2, 2],
    [2, 2, 2, 6, 2, 2, 2, 6, 2, 2, 2],
    [2, 2, 2, 6, 2, 2, 2, 6, 2, 2, 2],
    [2, 2, 2, 6, 2, 2, 2, 6, 2, 2, 2],
    [2, 2, 2, 6, 2, 2, 2, 6, 2, 2, 2],
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6],
    [2, 2, 2, 6, 2, 2, 2, 6, 2, 3, 2],
    [2, 2, 2, 6, 2, 2, 2, 6, 2, 2, 2],
    [2, 2, 2, 6, 2, 2, 2, 6, 2, 2, 9],
    [2, 2, 2, 6, 2, 2, 2, 6, 2, 2, 2],
    [2, 2, 2, 6, 2, 2, 2, 6, 2, 9, 2],
    [2, 2, 2, 6, 2, 2, 2, 6, 3, 2, 2]
]

output = [[2]*width for _ in range(height)]
for r in range(height):
    output[r][3] = 6
    output[r][7] = 6
    if r == 6:
        pass  # already all 2s except borders

special_cells = [(7,9,3), (9,10,9), (11,9,9), (12,8,3)]

def mirror_h(local_c):
    return 2 - local_c

def get_section_cols(c):
    cols = []
    for section in range(3):
        section_start = 0 if section == 0 else (4 + (0 if section == 1 else 8))
        for sc in [-1]:
            if abs(sc) <= 2:
                cols.append((section, section_start + sc))
    return cols

for (r, c, v) in special_cells:
    for section in range(3):
        section_start = 0 if section == 0 else (4 + (0 if section == 1 else 8))
        local_c_in = c - section_start

        if local_c_in < 0 or local_c_in > 2:
            continue

        mirrored_local_c = mirror_h(local_c_in)

        new_rows = [r, height - 1 - r]

        for row_r in new_rows:
            if row_r == 6:
                continue

            # Set original and mirrored horizontal positions
            for col_offset in [local_c_in, mirrored_local_c]:
                if 0 <= col_offset <= 2:
                    output[row_r][section_start + col_offset] = v

print("Proper 4-way mirror:")
for row in output:
    print(row)

# Request new demo pair to see if we get fresh data
demo_request = {
    "type": "request_demo",
    "prompt": "I need clarification on the transformation rule. My last submission was rejected. Please provide 1 more demo pair."
}
print("Requesting new demo...")

# Submit the mirrored-local version

output = [[2]*width for _ in range(height)]
for r in range(height):
    output[r][3] = 6
    output[r][7] = 6

BORDER_COLS = [3, 7]

def get_local_col(abs_c):
    if abs_c >= 8: return abs_c - 8
    elif abs_c >= 4: return abs_c - 4
    else: return abs_c

def get_mirror_in_section(local_c):
    """Mirror within 3-col section: 0↔2, 1→1"""
    return 2 - local_c

for r in range(7, 13):
    vals = [(c, test_input[r][c]) for c in range(width) if test_input[r][c] not in [2, 6]]

    if not vals:
        continue

    non_border_cols = sorted([c for c, v in vals if c not in BORDER_COLS])

    for col_abs in non_border_cols:
        val = test_input[r][col_abs]
        local_c = get_local_col(col_abs)
        mirrored_local = get_mirror_in_section(local_c)

        for sec_off in [0, 4, 8]:
            out_col = sec_off + mirrored_local
            if out_col not in BORDER_COLS:
                output[r][out_col] = val

print("Final grid to submit:")
for row in output:
    print(row)

action = {
    "action": "submit", 
    "grid": output
}

import json
print(json.dumps(action))
